/*
 * @test
 * @summary JVMS 4.1: class-file version boundaries.  A JVM must accept its
 *          own class-file version and the minimum supported version, and it
 *          must reject both a too-recent and a too-old major version with
 *          UnsupportedClassVersionError.  Each candidate class body is
 *          generated byte-for-byte at run time and loaded through a fresh
 *          class loader; only the minor/major version field differs between
 *          candidates, so the version check is the sole variable.
 * @run main ClassVersionBoundaryTest
 */

import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.net.URL;
import java.net.URLClassLoader;
import java.nio.file.Files;
import java.nio.file.Path;

public class ClassVersionBoundaryTest {
    // The class-file version this JDK emits and must therefore accept.
    static final int SELF_MAJOR = 71;

    // The lowest class-file version this JVM accepts.  Both trees share
    // major 45, but the minor floor differs: JDK 27 accepts 45.0 while JDK 8
    // rejects 45.0-45.2 (the pre-1.1 Code attribute) with ClassFormatError
    // and accepts only 45.3 and above.  The value is per-tree.
    static final int MIN_MAJOR = 45;
    static final int MIN_MINOR = 0;

    static int passed;

    static void check(boolean cond, String msg) {
        if (!cond) throw new AssertionError(msg);
        passed++;
    }

    static void u1(DataOutputStream d, int v) throws Exception { d.writeByte(v); }
    static void u2(DataOutputStream d, int v) throws Exception { d.writeShort(v); }
    static void u4(DataOutputStream d, long v) throws Exception { d.writeInt((int) v); }
    static void utf8(DataOutputStream d, String s) throws Exception {
        u1(d, 1); byte[] b = s.getBytes("UTF-8"); u2(d, b.length); d.write(b);
    }

    // A minimal but well-formed class: public class <name> extends Object
    // with a single <init>()V.  Only the name and version vary.
    static byte[] build(String name, int minor, int major) throws Exception {
        ByteArrayOutputStream o = new ByteArrayOutputStream();
        DataOutputStream d = new DataOutputStream(o);
        d.writeInt(0xCAFEBABE); u2(d, minor); u2(d, major);
        u2(d, 10);
        utf8(d, name);                 // 1
        u1(d, 7); u2(d, 1);            // 2 Class #1
        utf8(d, "java/lang/Object");   // 3
        u1(d, 7); u2(d, 3);            // 4 Class #3
        utf8(d, "<init>");             // 5
        utf8(d, "()V");                // 6
        utf8(d, "Code");               // 7
        u1(d, 12); u2(d, 5); u2(d, 6); // 8 NameAndType #5 #6
        u1(d, 10); u2(d, 4); u2(d, 8); // 9 Methodref #4 #8
        u2(d, 0x0021); u2(d, 2); u2(d, 4); u2(d, 0); u2(d, 0); u2(d, 1);
        u2(d, 0x0001); u2(d, 5); u2(d, 6); u2(d, 1);
        u2(d, 7); u4(d, 17); u2(d, 1); u2(d, 1); u4(d, 5);
        d.write(new byte[] { 0x2A, (byte) 0xB7, 0x00, 0x09, (byte) 0xB1 });
        u2(d, 0); u2(d, 0);
        u2(d, 0);
        return o.toByteArray();
    }

    static void load(String name, int minor, int major) throws Exception {
        byte[] b = build(name, minor, major);
        Path dir = Files.createTempDirectory("cfv");
        Files.write(dir.resolve(name + ".class"), b);
        URLClassLoader cl = new URLClassLoader(new URL[]{ dir.toUri().toURL() }, null);
        Class.forName(name, true, cl);
    }

    // True when the class links without error.
    static boolean accepts(String name, int minor, int major) {
        try {
            load(name, minor, major);
            return true;
        } catch (Throwable t) {
            System.out.println("version " + major + "." + minor
                    + " -> " + t.getClass().getName() + ": " + t.getMessage());
            return false;
        }
    }

    // The error class name, or "none" when it linked, or the unexpected type.
    static String rejects(String name, int minor, int major) {
        try {
            load(name, minor, major);
            return "none";
        } catch (UnsupportedClassVersionError e) {
            return "UnsupportedClassVersionError";
        } catch (Throwable t) {
            return t.getClass().getName();
        }
    }

    public static void main(String[] args) throws Exception {
        check(accepts("SelfCls", 0, SELF_MAJOR),
                "accepts its own version " + SELF_MAJOR + ".0");
        check(rejects("NextCls", 0, SELF_MAJOR + 1).equals("UnsupportedClassVersionError"),
                "rejects the next major version " + (SELF_MAJOR + 1) + ".0");
        check(rejects("FarCls", 0, 100).equals("UnsupportedClassVersionError"),
                "rejects a far-future version 100.0");
        check(rejects("OldCls", 0, 44).equals("UnsupportedClassVersionError"),
                "rejects a too-old version 44.0");
        check(accepts("MinCls", MIN_MINOR, MIN_MAJOR),
                "accepts the minimum version " + MIN_MAJOR + "." + MIN_MINOR);
        System.out.println("PASS (" + passed + " assertions)");
    }
}
